/**
 * ============================================================================
 * 視覺藝術作品署名與靈感宣告 (ATTRIBUTION & INSPIRATION DECLARATION)
 * ============================================================================
 * 作者 (Author / Code Adaptor): Uncler M
 * 靈感啟發來源 (Inspired By): Lawa - "把音乐律动化作流星轨迹！ Processing 3D粒子音乐可视化"
 * 原始作品討論 (Original Note): http://xhslink.com/o/78R2dEjIPfi
 * 授權協議 (License): Creative Commons Attribution-NonCommercial-ShareAlike 4.0 (CC BY-NC-SA 4.0)
 * 
 * [說明 / Notice]
 * 本作品由 Uncler M 編寫與視聽化對應。演算法靈感取材自 Lawa 創作之「3D 流星彗尾
 * 粒子與音域律動噴發」視覺概念。
 * 專為 4K MV Visual Integration Editor 專案打造。
 * ============================================================================
 */

let NUM_METEORS = 220;
let MAX_TRAIL = 14;
let meteors = [];
let rotAngleX = 0, rotAngleY = 0;

let smoothedSubBass = 0.0;
let smoothedPercussive = 0.0;
let smoothedMid = 0.0;

setup = () => {
  p5.disableFriendlyErrors = true;
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 1.0);
  ellipseMode(CENTER);

  // 初始化流星粒子群
  for (let i = 0; i < NUM_METEORS; i++) {
    resetMeteor(i);
  }
};

function resetMeteor(idx) {
  let theta = random(TWO_PI);
  let phi = random(-PI * 0.4, PI * 0.4);
  let speed = random(4.0, 12.0);
  let radius = random(30, 100);

  meteors[idx] = {
    x: radius * cos(phi) * cos(theta),
    y: radius * sin(phi),
    z: radius * cos(phi) * sin(theta),
    vx: cos(phi) * cos(theta) * speed,
    vy: sin(phi) * speed,
    vz: cos(phi) * sin(theta) * speed,
    trail: [],
    size: random(2.0, 5.0),
    maxLife: random(60, 140),
    life: 0
  };
}

draw = () => {
  // 1. 動態音訊信號平滑處理
  let rawSubBass = (typeof sub_bass !== 'undefined') ? sub_bass : (typeof sub_bass_ratio !== 'undefined' ? sub_bass_ratio : (mouseIsPressed ? 0.85 : 0.25));
  let rawPercussive = (typeof percussive !== 'undefined') ? percussive : (mouseIsPressed ? 0.9 : 0.1);
  let rawMid = (typeof mid !== 'undefined') ? mid : (typeof mid_ratio !== 'undefined' ? mid_ratio : 0.3);

  smoothedSubBass += (rawSubBass - smoothedSubBass) * 0.15;
  smoothedPercussive += (rawPercussive - smoothedPercussive) * 0.3;
  smoothedMid += (rawMid - smoothedMid) * 0.2;

  // 2. 尾蹟發光沖刷背景
  background(235, 40, 5, 0.2);

  // 3. 3D 空間視角旋轉
  rotAngleX += 0.004 + smoothedMid * 0.012;
  rotAngleY += 0.006 + smoothedSubBass * 0.018;

  let cx = width * 0.5;
  let cy = height * 0.5;
  let currentHue = (typeof chord_hue !== 'undefined' && chord_hue > 0) ? chord_hue : 185;

  // 4. 重低頻爆發：噴發額外高速流星雨
  if (smoothedSubBass > 0.6 && random() < 0.3) {
    let burstIdx = int(random(NUM_METEORS));
    let dirTheta = random(TWO_PI);
    let dirPhi = random(-PI * 0.3, PI * 0.3);
    let burstSpeed = random(18.0, 32.0);

    meteors[burstIdx].x = 0;
    meteors[burstIdx].y = 0;
    meteors[burstIdx].z = 0;
    meteors[burstIdx].vx = cos(dirPhi) * cos(dirTheta) * burstSpeed;
    meteors[burstIdx].vy = sin(dirPhi) * burstSpeed;
    meteors[burstIdx].vz = cos(dirPhi) * sin(dirTheta) * burstSpeed;
    meteors[burstIdx].trail = [];
    meteors[burstIdx].life = 0;
  }

  // 5. 更新與渲染流星粒子與彗尾 (Meteor & Trail Render Loop)
  let projectedMeteors = [];

  for (let i = 0; i < NUM_METEORS; i++) {
    let m = meteors[i];
    m.life++;

    if (m.life > m.maxLife || abs(m.x) > width || abs(m.y) > height || abs(m.z) > 1200) {
      resetMeteor(i);
      continue;
    }

    // 紀錄彗尾歷史位置佇列
    m.trail.push({ x: m.x, y: m.y, z: m.z });
    if (m.trail.length > MAX_TRAIL) {
      m.trail.shift();
    }

    // 速度更新 (包含微幅重力加速度)
    m.x += m.vx * (1.0 + smoothedSubBass * 0.8);
    m.y += m.vy * (1.0 + smoothedSubBass * 0.8);
    m.z += m.vz * (1.0 + smoothedSubBass * 0.8);

    // 3D 矩陣旋轉與投影
    let projTrail = [];
    for (let t = 0; t < m.trail.length; t++) {
      let tp = m.trail[t];
      let rx = tp.x * cos(rotAngleY) + tp.z * sin(rotAngleY);
      let rz = -tp.x * sin(rotAngleY) + tp.z * cos(rotAngleY);

      let ry = tp.y * cos(rotAngleX) - rz * sin(rotAngleX);
      let finalZ = tp.y * sin(rotAngleX) + rz * cos(rotAngleX);

      let scale = 420 / (420 + finalZ + 200);
      projTrail.push({
        px: cx + rx * scale,
        py: cy + ry * scale,
        pz: finalZ,
        scale: scale
      });
    }

    if (projTrail.length > 1) {
      projectedMeteors.push({
        projTrail: projTrail,
        headZ: projTrail[projTrail.length - 1].pz,
        size: m.size
      });
    }
  }

  // 按 Z 深度排序（近大遠小，由遠至近繪製）
  projectedMeteors.sort((a, b) => b.headZ - a.headZ);

  // 6. 繪製流星發光彗尾與星核
  for (let i = 0; i < projectedMeteors.length; i++) {
    let pm = projectedMeteors[i];
    let trail = pm.projTrail;

    // (A) 彗尾線條 (Meteor Trail Lines)
    for (let t = 0; t < trail.length - 1; t++) {
      let pt1 = trail[t];
      let pt2 = trail[t + 1];
      let alpha = map(t, 0, trail.length - 1, 0.05, 0.95);
      let hueVal = (currentHue + t * 8.0) % 360;

      stroke(hueVal, 85, 100, alpha);
      strokeWeight((0.8 + (t / trail.length) * pm.size) * pt2.scale * (1.0 + smoothedSubBass * 0.8));
      line(pt1.px, pt1.py, pt2.px, pt2.py);
    }

    // (B) 流星頭部發光星核 (Meteor Head Glow)
    let head = trail[trail.length - 1];
    noStroke();
    fill((currentHue + 40) % 360, 40, 100, 0.95);
    ellipse(head.px, head.py, (pm.size * 2.5 + smoothedPercussive * 6.0) * head.scale, (pm.size * 2.5 + smoothedPercussive * 6.0) * head.scale);
  }

  // 7. 重拍繁星閃爍光斑 (Stellar Sparkle Effect)
  if (smoothedPercussive > 0.5) {
    let sparkles = int(smoothedPercussive * 12);
    for (let s = 0; s < sparkles; s++) {
      let sx = random(width);
      let sy = random(height);
      fill(0, 0, 100, random(0.5, 0.95));
      ellipse(sx, sy, random(2.0, 5.0), random(2.0, 5.0));
    }
  }
};

